// @FIGURE_CODE_BEGIN
/* ── Element spec ───────────────────────────────────────────────────────────
   camera centre O      → SphereGeometry(0.09)                    black
   image plane          → LineLoop 4 corners z=2                  #3A3A3A  (+ faint fill mesh)
   3D bird (x8 trail)   → THREE.Shape → ShapeGeometry (white) + LineLoop (black), billboarded
   current bird         → same, solid, at P(t)
   3D velocity arrows   → cylinder shaft + cone head              #E8262A (thick)
   green rays O→bird    → THREE.Line (2 pts)                      #00D000
   projected birds      → same Shape, scaled f/Pz, on plane
   image-velocity arrows→ thin cylinder + cone                    #E8262A
   vanishing point      → SphereGeometry(0.035)                   black
   extended ray O→VP→∞  → THREE.Line                              #00D000
   V arrow on that ray  → cylinder + cone                         #E8262A
   drag handle          → SphereGeometry(0.09)                    #0aa00a
   labels O, V, V, "Vanishing point" → addLabel (serif)
────────────────────────────────────────────────────────────────────────────*/

const FOCAL = 2.0;
const PLANE_HX = 1.5, PLANE_HY = 1.2;
const P0 = new THREE.Vector3(-0.7, 0.7, 1.4);
const SPEED = 1.795;
const UP = new THREE.Vector3(0, 1, 0);
const ORIGIN = new THREE.Vector3(0, 0, 0);
const GREEN = 0x00c400, RED = 0xE8262A, GRAY = 0x3A3A3A;
const TR = [0, 0.7, 1.4, 2.1, 2.8, 3.5, 4.2, 4.9];
const BIRD3D = 0.48;

let vAzDeg = 26.6, vElDeg = 4.8;
const V = new THREE.Vector3();
function updateV() {
  const a = THREE.MathUtils.degToRad(vAzDeg), e = THREE.MathUtils.degToRad(vElDeg);
  V.set(Math.sin(a) * Math.cos(e), Math.sin(e), Math.cos(a) * Math.cos(e)).multiplyScalar(SPEED);
}
updateV();
function birdPos(t) { return new THREE.Vector3(P0.x + V.x * t, P0.y + V.y * t, P0.z + V.z * t); }
function projOn(p, eps) {
  const z = Math.max(0.15, p.z);
  return new THREE.Vector3(FOCAL * p.x / z, FOCAL * p.y / z, FOCAL - (eps || 0));
}

/* ── groups ────────────────────────────────────────────────────────────── */
const world3D = new THREE.Group();
const planeGroup = new THREE.Group();
scene.add(world3D); scene.add(planeGroup);

/* ── bird silhouette ───────────────────────────────────────────────────── */
const BIRD_PTS = [
  [-0.50, 0.32], [-0.30, 0.03], [-0.12, -0.02], [-0.08, -0.12], [-0.10, -0.30],
  [0.00, -0.21], [0.10, -0.30], [0.08, -0.12], [0.12, -0.02], [0.30, 0.03],
  [0.50, 0.32], [0.16, 0.10], [0.07, 0.16], [0.01, 0.27], [-0.07, 0.16], [-0.16, 0.10]
];
function birdShape() {
  const s = new THREE.Shape();
  s.moveTo(BIRD_PTS[0][0], BIRD_PTS[0][1]);
  for (let i = 1; i < BIRD_PTS.length; i++) s.lineTo(BIRD_PTS[i][0], BIRD_PTS[i][1]);
  s.closePath();
  return s;
}
const BIRD_SHAPE = birdShape();
const BIRD_GEO = new THREE.ShapeGeometry(BIRD_SHAPE);
const BIRD_OUT_GEO = new THREE.BufferGeometry().setFromPoints(
  BIRD_PTS.map(p => new THREE.Vector3(p[0], p[1], 0)));

function makeBird() {
  const g = new THREE.Group();
  const fill = new THREE.Mesh(BIRD_GEO, new THREE.MeshBasicMaterial({
    color: 0xffffff, side: THREE.DoubleSide, transparent: true, opacity: 1
  }));
  const outline = new THREE.LineLoop(BIRD_OUT_GEO, new THREE.LineBasicMaterial({
    color: 0x000000, transparent: true, opacity: 1
  }));
  outline.position.z = 0.001;
  g.add(fill); g.add(outline);
  g.userData.fill = fill; g.userData.outline = outline;
  return g;
}
function setBirdOpacity(b, o) {
  b.userData.fill.material.opacity = o;
  b.userData.outline.material.opacity = o;
}

/* ── line + arrow helpers ──────────────────────────────────────────────── */
function makeLine(color, opacity) {
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  return new THREE.Line(geo, new THREE.LineBasicMaterial({ color, transparent: true, opacity }));
}
function setLine(line, a, b) {
  const p = line.geometry.attributes.position;
  p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z);
  p.needsUpdate = true;
  line.geometry.computeBoundingBox(); line.geometry.computeBoundingSphere();
}
function makeArrow(color, shaftR, headR, headL) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const g = new THREE.Group();
  const sg = new THREE.CylinderGeometry(shaftR, shaftR, 1, 12); sg.translate(0, 0.5, 0);
  const hg = new THREE.ConeGeometry(headR, headL, 16); hg.translate(0, headL / 2, 0);
  const shaft = new THREE.Mesh(sg, mat), head = new THREE.Mesh(hg, mat);
  g.add(shaft); g.add(head);
  g.userData.mat = mat;
  g.setFromTo = function (a, b) {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    if (len < 1e-3) { this.visible = false; return; }
    this.visible = true;
    dir.divideScalar(len);
    this.position.copy(a);
    this.quaternion.setFromUnitVectors(UP, dir);
    const hl = Math.min(headL, len * 0.6);
    head.scale.set(1, hl / headL, 1);
    head.position.y = len - hl;
    shaft.scale.set(1, Math.max(1e-4, len - hl), 1);
  };
  return g;
}

/* ── camera centre O ───────────────────────────────────────────────────── */
const oSphere = new THREE.Mesh(new THREE.SphereGeometry(0.09, 24, 18),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));
world3D.add(oSphere);
registerInteractive(oSphere, {
  title: 'Camera centre O',
  tooltip: 'Camera centre O',
  body: 'Every projection ray passes through this single point. A world point P is imaged where the line OP pierces the image plane, giving p = f·(Px/Pz, Py/Pz).'
});

/* ── image plane ───────────────────────────────────────────────────────── */
const planeFill = new THREE.Mesh(
  new THREE.PlaneGeometry(2 * PLANE_HX, 2 * PLANE_HY),
  new THREE.MeshBasicMaterial({ color: 0xdddddd, transparent: true, opacity: 0.06, side: THREE.DoubleSide, depthWrite: false })
);
planeFill.position.set(0, 0, FOCAL);
planeGroup.add(planeFill);
const planeOutline = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-PLANE_HX, -PLANE_HY, FOCAL), new THREE.Vector3(PLANE_HX, -PLANE_HY, FOCAL),
    new THREE.Vector3(PLANE_HX, PLANE_HY, FOCAL), new THREE.Vector3(-PLANE_HX, PLANE_HY, FOCAL)
  ]),
  new THREE.LineBasicMaterial({ color: GRAY })
);
planeGroup.add(planeOutline);
registerInteractive(planeFill, {
  title: 'Image plane (Z = f)',
  tooltip: 'Image plane',
  body: 'The plane sits a focal length f = 2 in front of O. Orbit the scene: the projected birds really lie on this flat plane — the convergence is a depth effect, not a drawing trick.'
});

/* ── trail birds, rays, 3D arrows, projected birds, image arrows ───────── */
const trailBirds = [], rays = [], projBirds = [], arrows3D = [], imgArrows = [];
for (let i = 0; i < TR.length; i++) {
  const b = makeBird(); world3D.add(b); trailBirds.push(b);
  const r = makeLine(GREEN, 0.95); world3D.add(r); rays.push(r);
  const pb = makeBird(); planeGroup.add(pb); projBirds.push(pb);
}
for (let i = 0; i < TR.length - 1; i++) {
  const a = makeArrow(RED, 0.035, 0.11, 0.26); world3D.add(a); arrows3D.push(a);
}
for (let i = 0; i < TR.length; i++) {          // 7 between birds + 1 into the VP
  const a = makeArrow(RED, 0.008, 0.028, 0.065); planeGroup.add(a); imgArrows.push(a);
}
registerInteractive(trailBirds[2], {
  title: 'Equal time steps in 3D',
  tooltip: 'Bird at a sampled time',
  body: 'Consecutive trail birds are separated by the same Δt, so the red 3D arrows between them all have the same length |V|·Δt. The bird never slows down.'
});

/* ── current bird / ray / projection ───────────────────────────────────── */
const curBird = makeBird(); world3D.add(curBird);
const curRay = makeLine(GREEN, 1); world3D.add(curRay);
const curDot = new THREE.Mesh(new THREE.SphereGeometry(0.045, 16, 12),
  new THREE.MeshBasicMaterial({ color: 0x008000 })); world3D.add(curDot);
const curProjBird = makeBird(); planeGroup.add(curProjBird);
const curProjDot = new THREE.Mesh(new THREE.SphereGeometry(0.022, 14, 10),
  new THREE.MeshBasicMaterial({ color: 0x008000 })); planeGroup.add(curProjDot);

/* ── vanishing point + extended direction ray ──────────────────────────── */
const vpDot = new THREE.Mesh(new THREE.SphereGeometry(0.038, 20, 14),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));
planeGroup.add(vpDot);
registerInteractive(vpDot, {
  title: 'Vanishing point (focus of expansion)',
  tooltip: 'Vanishing point',
  body: 'VP = f·(Vx/Vz, Vy/Vz): the limit of the image as Z → ∞. It depends only on the DIRECTION of V, not on where the bird started, and the image velocity tends to zero there.'
});
const extRay = makeLine(GREEN, 1); world3D.add(extRay);
const extArrow = makeArrow(RED, 0.035, 0.11, 0.26); world3D.add(extArrow);
const handle = new THREE.Mesh(new THREE.SphereGeometry(0.1, 20, 14),
  new THREE.MeshBasicMaterial({ color: 0x0aa00a }));
world3D.add(handle);
registerInteractive(handle, {
  title: 'Drag to turn V',
  tooltip: 'Drag to turn the velocity V',
  body: 'This handle rides the ray O→VP, which is parallel to V. Drag it: the vanishing point relocates to the image of the new direction.'
});

/* ── state + update ────────────────────────────────────────────────────── */
let tCur = 1.2;
const projPts = new Array(TR.length);

function update() {
  updateV();
  const vhat = V.clone().normalize();

  for (let i = 0; i < TR.length; i++) {
    const ti = TR[i], p = birdPos(ti);
    const solid = ti <= tCur + 1e-6;
    const b = trailBirds[i];
    b.position.copy(p);
    b.quaternion.copy(camera.quaternion);
    b.scale.setScalar(BIRD3D);
    setBirdOpacity(b, solid ? 1 : 0.4);

    setLine(rays[i], ORIGIN, p);
    rays[i].material.opacity = solid ? 0.95 : 0.3;

    const q = projOn(p, 0.012);
    projPts[i] = q;
    const pb = projBirds[i];
    pb.position.copy(q);
    pb.scale.setScalar(Math.max(0.05, 0.28 * FOCAL / Math.max(0.2, p.z)));
    setBirdOpacity(pb, solid ? 1 : 0.3);
  }

  const vp = new THREE.Vector3(FOCAL * V.x / V.z, FOCAL * V.y / V.z, FOCAL - 0.014);
  vpDot.position.copy(vp);

  for (let i = 0; i < TR.length - 1; i++) {
    const a = projPts[i].clone(), b = projPts[i + 1].clone();
    const dir = new THREE.Vector3().subVectors(b, a);
    const L = dir.length();
    if (L < 1e-3) { imgArrows[i].visible = false; }
    else {
      dir.divideScalar(L);
      const gap = Math.min(0.09, L * 0.25);
      imgArrows[i].setFromTo(a.addScaledVector(dir, gap), b.addScaledVector(dir, -gap * 0.6));
      imgArrows[i].userData.mat.opacity = TR[i + 1] <= tCur + 1e-6 ? 1 : 0.35;
    }
  }
  {
    const a = projPts[TR.length - 1].clone(), b = vp.clone();
    const dir = new THREE.Vector3().subVectors(b, a); const L = dir.length();
    if (L < 0.05) imgArrows[TR.length - 1].visible = false;
    else {
      dir.divideScalar(L);
      imgArrows[TR.length - 1].setFromTo(a.addScaledVector(dir, L * 0.2), b.addScaledVector(dir, -0.05));
      imgArrows[TR.length - 1].userData.mat.opacity = 0.9;
    }
  }

  for (let i = 0; i < TR.length - 1; i++) {
    const a = birdPos(TR[i]).addScaledVector(vhat, 0.34);
    const b = birdPos(TR[i + 1]).addScaledVector(vhat, -0.34);
    arrows3D[i].setFromTo(a, b);
    arrows3D[i].userData.mat.opacity = TR[i + 1] <= tCur + 1e-6 ? 1 : 0.4;
  }

  const pc = birdPos(tCur);
  curBird.position.copy(pc);
  curBird.quaternion.copy(camera.quaternion);
  curBird.scale.setScalar(BIRD3D);
  curDot.position.copy(pc);
  setLine(curRay, ORIGIN, pc);
  const qc = projOn(pc, 0.02);
  curProjBird.position.copy(qc);
  curProjBird.scale.setScalar(Math.max(0.05, 0.28 * FOCAL / Math.max(0.2, pc.z)));
  curProjDot.position.copy(qc);

  const far = vhat.clone().multiplyScalar(7.2);
  setLine(extRay, ORIGIN, far);
  const aS = vhat.clone().multiplyScalar(2.9), aE = vhat.clone().multiplyScalar(4.15);
  extArrow.setFromTo(aS, aE);
  handle.position.copy(vhat).multiplyScalar(5.3);

  if (labV3) labV3.pos.copy(birdPos(TR[3]).lerp(birdPos(TR[4]), 0.5)).add(new THREE.Vector3(0, 0.42, 0));
  if (labVe) labVe.pos.copy(aS.clone().lerp(aE, 0.5)).add(new THREE.Vector3(0, 0.3, 0));
  if (labVP) labVP.pos.copy(vp);
}

/* first build, then frame the camera ──────────────────────────────────── */
let labV3 = null, labVe = null, labVP = null;
update();
setCameraView({ projection: 'perspective', azimuthDeg: 218, elevationDeg: 16, rollDeg: 0, heightFraction: 0.7 });

/* ── labels ────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,\'Times New Roman\',serif';
const labO = addLabel(`<span style="${SER}">O</span>`, new THREE.Vector3(0, 0, 0),
  { fontSize: '17px', offset: [-16, 20] });
labV3 = addLabel(`<span style="${SER};font-weight:bold">V</span>`, new THREE.Vector3(),
  { fontSize: '17px', offset: [0, -4] });
labVe = addLabel(`<span style="${SER};font-weight:bold">V</span>`, new THREE.Vector3(),
  { fontSize: '17px', offset: [0, -4] });
labVP = addLabel(`<span style="${SER}">Vanishing point</span>`, new THREE.Vector3(),
  { fontSize: '15px', offset: [62, 22] });
const labels3DOnly = [labO, labV3, labVe];

/* ── UI wiring ─────────────────────────────────────────────────────────── */
document.getElementById('btnReset').style.display = '';
const elT = document.getElementById('tScrub'), elTVal = document.getElementById('tVal');
const elPlay = document.getElementById('btnPlay');
const elAz = document.getElementById('vAz'), elEl = document.getElementById('vEl');
const elAzVal = document.getElementById('azVal'), elElVal = document.getElementById('elVal');
const b3d = document.getElementById('vm3d'), bcam = document.getElementById('vmCam');
const stTitle = document.getElementById('stepTitle'), stNarr = document.getElementById('stepNarr');

let playing = false, tweenTarget = null, viewMode = '3D scene';

function syncT() { elT.value = tCur.toFixed(2); elTVal.textContent = tCur.toFixed(2); }
syncT();
elT.addEventListener('input', () => { tCur = parseFloat(elT.value); tweenTarget = null; playing = false; elPlay.textContent = '▶ Fly at constant velocity V'; elPlay.classList.remove('active'); elTVal.textContent = tCur.toFixed(2); });
elPlay.addEventListener('click', () => {
  playing = !playing; tweenTarget = null;
  elPlay.textContent = playing ? '❚❚ Pause flight' : '▶ Fly at constant velocity V';
  elPlay.classList.toggle('active', playing);
});
elAz.addEventListener('input', () => { vAzDeg = parseFloat(elAz.value); elAzVal.textContent = elAz.value; });
elEl.addEventListener('input', () => { vElDeg = parseFloat(elEl.value); elElVal.textContent = elEl.value; });

function setViewMode(m) {
  viewMode = m;
  b3d.classList.toggle('active', m === '3D scene');
  bcam.classList.toggle('active', m === 'Camera image');
  if (m === 'Camera image') {
    if (world3D.parent) scene.remove(world3D);
    labels3DOnly.forEach(l => l.div.style.visibility = 'hidden');
    setCameraView({ projection: 'perspective', azimuthDeg: -90, elevationDeg: 0, rollDeg: 0, target: [0, 0, FOCAL], heightFraction: 0.92 });
  } else {
    if (!world3D.parent) scene.add(world3D);
    labels3DOnly.forEach(l => l.div.style.visibility = 'visible');
    setCameraView({ projection: 'perspective', azimuthDeg: 218, elevationDeg: 16, rollDeg: 0, heightFraction: 0.7 });
  }
}
b3d.addEventListener('click', () => setViewMode('3D scene'));
bcam.addEventListener('click', () => setViewMode('Camera image'));

/* ── guided tour ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: '1. Bird near the camera', narration: 'Early in the flight the bird is close and off to the left; its green ray pierces the image plane far from the vanishing point, and one time step moves the image a long way.', view: '3D scene', t: 0.2 },
  { title: '2. Equal 3D steps, shrinking image steps', narration: 'Scrub forward: the thick red 3D arrows V stay the same length, but the thin red arrows between projected birds on the plane get shorter and shorter.', view: '3D scene', t: 2.0 },
  { title: '3. Converging on the vanishing point', narration: 'As the bird recedes its image crowds onto the black dot. The vanishing point is the limit of the projection as Z → ∞, and the image velocity tends to zero.', view: '3D scene', t: 5.0 },
  { title: '4. From the camera’s seat', narration: 'Switch to the image plane itself: the whole flight is a track of shrinking birds sliding into the focus of expansion, with velocity arrows all aimed at it.', view: 'Camera image', t: 3.0 },
  { title: '5. Turn the velocity', narration: 'Drag the green handle (or the direction sliders) and play the loop again — the vanishing point relocates to the image of the new direction, proving the FOE encodes the translation direction.', view: '3D scene', t: 2.5 }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  if (viewMode !== s.view) setViewMode(s.view);
  playing = false; elPlay.textContent = '▶ Fly at constant velocity V'; elPlay.classList.remove('active');
  tweenTarget = s.t;
  stTitle.textContent = s.title;
  stNarr.textContent = s.narration;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── drag the velocity handle ──────────────────────────────────────────── */
const _rc = new THREE.Raycaster();
const _nd = new THREE.Vector2();
let dragging = false;
function ndcFrom(e) {
  const r = canvas.getBoundingClientRect();
  _nd.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  _nd.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
window.addEventListener('pointerdown', (e) => {
  if (viewMode !== '3D scene' || e.target !== canvas) return;
  ndcFrom(e);
  _rc.setFromCamera(_nd, camera);
  if (_rc.intersectObject(handle, false).length) {
    dragging = true;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.stopPropagation(); e.preventDefault();
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  ndcFrom(e);
  _rc.setFromCamera(_nd, camera);
  const R = 5.3;
  const hit = new THREE.Vector3();
  let dir;
  if (_rc.ray.intersectSphere(new THREE.Sphere(ORIGIN, R), hit)) dir = hit.clone().normalize();
  else { const cp = new THREE.Vector3(); _rc.ray.closestPointToPoint(ORIGIN, cp); dir = cp.normalize(); }
  if (!isFinite(dir.x)) return;
  if (dir.z < 0.25) { dir.z = 0.25; dir.normalize(); }
  let el = THREE.MathUtils.radToDeg(Math.asin(THREE.MathUtils.clamp(dir.y, -1, 1)));
  let az = THREE.MathUtils.radToDeg(Math.atan2(dir.x, dir.z));
  vElDeg = THREE.MathUtils.clamp(el, -25, 25);
  vAzDeg = THREE.MathUtils.clamp(az, -60, 60);
  elAz.value = vAzDeg.toFixed(0); elAzVal.textContent = vAzDeg.toFixed(0);
  elEl.value = vElDeg.toFixed(0); elElVal.textContent = vElDeg.toFixed(0);
  e.stopPropagation(); e.preventDefault();
}, true);
window.addEventListener('pointerup', () => {
  if (!dragging) return;
  dragging = false; controls.enabled = true; canvas.style.cursor = 'default';
}, true);

/* ── own animation loop (scaffold's animate() renders) ─────────────────── */
let _last = performance.now();
function figLoop() {
  requestAnimationFrame(figLoop);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  if (playing) {
    tCur += dt * 0.7;
    if (tCur > 5) tCur = 0;
    syncT();
  } else if (tweenTarget !== null) {
    tCur += (tweenTarget - tCur) * Math.min(1, dt * 7);
    if (Math.abs(tweenTarget - tCur) < 0.01) { tCur = tweenTarget; tweenTarget = null; }
    syncT();
  }
  update();
}
figLoop();
