Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font:700 13px sans-serif;margin-bottom:2px">Vanishing point of a translating bird</div>
<div style="font-size:11px;line-height:1.4;color:#333">A bird flies at constant 3D velocity <b>V</b>. Green rays from the camera centre <b>O</b> project it onto the image plane, where its image crowds into the <b>vanishing point</b> (focus of expansion).</div>
<button id="btnPlay">▶ Fly at constant velocity V</button>
<label><span>Time <i>t</i> along path: <b id="tVal">1.20</b> s</span>
  <input id="tScrub" type="range" min="0" max="5" step="0.05" value="1.2">
</label>
<div style="font-weight:700;margin-top:4px">View</div>
<div style="display:flex;gap:4px">
  <button id="vm3d" class="active">3D scene</button>
  <button id="vmCam">Camera image</button>
</div>
<div style="font-weight:700;margin-top:4px">Direction of V</div>
<label><span>turn (°): <b id="azVal">27</b></span>
  <input id="vAz" type="range" min="-60" max="60" step="1" value="27">
</label>
<label><span>tilt (°): <b id="elVal">5</b></span>
  <input id="vEl" type="range" min="-25" max="25" step="1" value="5">
</label>
<div style="font-size:10px;color:#555">…or drag the green handle on the long ray in the 3D view.</div>
<div style="font-weight:700;margin-top:4px">Guided tour</div>
<div style="display:flex;gap:4px">
  <button id="stepPrev">◀ Prev</button>
  <button id="stepNext">Next ▶</button>
</div>
<div id="stepTitle" style="font-weight:700;font-size:11px"></div>
<div id="stepNarr" style="font-size:11px;line-height:1.4;color:#222">Press “Next ▶” to walk through the construction.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per drawn element) ──────────────────────────────
   camera centre O        → SphereGeometry(0.11)                  black
   image plane edges      → 4 × CylinderGeometry rods r=0.014     #3A3A3A
   image plane fill       → PlaneGeometry(3,2.4) opacity .05      grey (pick target)
   3D birds (8 trail)     → THREE.Shape → ShapeGeometry white + scaled black behind, billboard
   current bird           → same, scaled 1.08, + green dot
   3D velocity arrows (7) → cylinder shaft r=.09 + cone head      #E8262A full saturation
   green rays O→bird (8)  → CylinderGeometry rods r=.018          #00C400
   extended ray O→VP→far  → rod r=.018                            #00C400
   V arrow on that ray    → cylinder + cone                       #E8262A
   projected birds (8)    → same Shape scaled f/Pz, coplanar with plane
   image-velocity arrows  → thin cylinder + cone, tapering        #E8262A
   vanishing point        → SphereGeometry(0.055)                 black
   drag handle            → SphereGeometry(0.13)                  #0aa00a
   labels O, V, V, "Vanishing point" → addLabel, serif, size-compensated
────────────────────────────────────────────────────────────────────────────*/

const FOCAL = 2.0;
const PLANE_HX = 1.5, PLANE_HY = 1.2;
const P0 = new THREE.Vector3(-1.55, 1.35, 2.7);   // start well BEYOND the image plane
const SPEED = 2.8;
const UP = new THREE.Vector3(0, 1, 0);
const ORIGIN = new THREE.Vector3(0, 0, 0);
const GREEN = 0x00c400, RED = 0xE8262A, GRAY = 0x3A3A3A;
const TR = [0, 0.7, 1.4, 2.1, 2.8, 3.5, 4.2, 4.9];
const BIRD3D = 0.95;
const PROJ_K = 0.85;
const RAY_R = 0.018;

let vAzDeg = 26.6, vElDeg = 4.8;
const V = new THREE.Vector3();
function updateV() {
  const a = THREE.MathUtils.degToRad(vAzDeg), e = THREE.MathUtils.degToRad(vElDeg);
  V.set(Math.sin(a) * Math.cos(e), Math.sin(e), Math.cos(a) * Math.cos(e)).multiplyScalar(SPEED);
}
updateV();
function birdPos(t) { return new THREE.Vector3(P0.x + V.x * t, P0.y + V.y * t, P0.z + V.z * t); }
function projOn(p, eps) {
  const z = Math.max(0.25, p.z);
  return new THREE.Vector3(FOCAL * p.x / z, FOCAL * p.y / z, FOCAL - (eps || 0));
}

/* ── groups ────────────────────────────────────────────────────────────── */
const world3D = new THREE.Group();
const planeGroup = new THREE.Group();
scene.add(world3D); scene.add(planeGroup);

/* ── bird silhouette ───────────────────────────────────────────────────── */
const BIRD_PTS = [
  [-0.50, 0.32], [-0.30, 0.03], [-0.12, -0.02], [-0.08, -0.12], [-0.10, -0.30],
  [0.00, -0.21], [0.10, -0.30], [0.08, -0.12], [0.12, -0.02], [0.30, 0.03],
  [0.50, 0.32], [0.16, 0.10], [0.07, 0.16], [0.01, 0.27], [-0.07, 0.16], [-0.16, 0.10]
];
const BIRD_SHAPE = (() => {
  const s = new THREE.Shape();
  s.moveTo(BIRD_PTS[0][0], BIRD_PTS[0][1]);
  for (let i = 1; i < BIRD_PTS.length; i++) s.lineTo(BIRD_PTS[i][0], BIRD_PTS[i][1]);
  s.closePath(); return s;
})();
const BIRD_GEO = new THREE.ShapeGeometry(BIRD_SHAPE);
const BIRD_OUT_GEO = new THREE.BufferGeometry().setFromPoints(
  BIRD_PTS.map(p => new THREE.Vector3(p[0], p[1], 0)));

function makeBird(order) {
  const g = new THREE.Group();
  const back = new THREE.Mesh(BIRD_GEO, new THREE.MeshBasicMaterial({
    color: 0x000000, side: THREE.DoubleSide, transparent: true, opacity: 1, depthWrite: false
  }));
  back.scale.set(1.16, 1.16, 1);
  back.renderOrder = order;
  const fill = new THREE.Mesh(BIRD_GEO, new THREE.MeshBasicMaterial({
    color: 0xffffff, side: THREE.DoubleSide, transparent: true, opacity: 1, depthWrite: false
  }));
  fill.position.z = 0.004; fill.renderOrder = order + 1;
  const outline = new THREE.LineLoop(BIRD_OUT_GEO, new THREE.LineBasicMaterial({
    color: 0x000000, transparent: true, opacity: 1, depthWrite: false
  }));
  outline.position.z = 0.008; outline.renderOrder = order + 2;
  g.add(back); g.add(fill); g.add(outline);
  g.userData.parts = [back.material, fill.material, outline.material];
  return g;
}

/* ── rod / arrow helpers ───────────────────────────────────────────────── */
function makeRod(color, r, order) {
