<div style="font-weight:700;margin-top:4px">Direction of V</div>
<label><span>turn (°): <b id="azVal">27</b></span>
  <input id="vAz" type="range" min="-35" max="35" step="1" value="27">
</label>
<label><span>tilt (°): <b id="elVal">5</b></span>
  <input id="vEl" type="range" min="-20" max="20" step="1" value="5">
</label>
<div style="font-size:10px;color:#555">…or drag the small green handle on the long ray in the 3D view.</div>
<div style="font-weight:700;margin-top:4px">Guided tour</div>
<div style="display:flex;gap:4px">
  <button id="stepPrev">◀ Prev</button>
  <button id="stepNext">Next ▶</button>
</div>
<div id="stepTitle" style="font-weight:700;font-size:11px"></div>
<div id="stepNarr" style="font-size:11px;line-height:1.4;color:#222">Press “Next ▶” to walk through the construction.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per drawn element) ──────────────────────────────
   camera centre O          → SphereGeometry(0.10)                     black
   image plane outline      → 4 × CylinderGeometry rods r=0.012        #3A3A3A (no fill)
   image plane pick target  → PlaneGeometry(3,2.4) opacity 0           invisible
   3D birds (8 trail)       → THREE.Shape gull silhouette, 0.35 wide   white + black halo, billboard
   current bird             → same shape ×1.1 + green dot              white/green
   3D velocity arrows (7)   → cyl r=.042 + cone r=.105 L=.28           #E8262A, equal length
   green rays O→bird (8)    → rods r=.016, 40% opacity once passed     #00C400
   extended ray O→VP→far    → rod r=.016                               #00C400
   V arrow on that ray      → cyl+cone, same size as 3D arrows         #E8262A
   projected birds (8)      → same Shape scaled f/Pz, coplanar z=f     white + black halo
   image-velocity arrows(8) → thin cyl r=.013 + cone r=.036            #E8262A, shrink like 1/Z²
   vanishing point          → SphereGeometry(0.035)                    black
   drag handle              → SphereGeometry(0.11)                     #0a9a0a
   labels O, V, V, 'Vanishing point' → addLabel, serif, px-compensated
────────────────────────────────────────────────────────────────────────────*/

const FOCAL = 2.0;
const PLANE_HX = 1.5, PLANE_HY = 1.2;
const P0 = new THREE.Vector3(-0.7, 0.7, 1.4);
const SPEED = 1.797;                       // |V| = |(0.8,0.15,1.6)|
const UP = new THREE.Vector3(0, 1, 0);
const ORIGIN = new THREE.Vector3(0, 0, 0);
const GREEN = 0x00c400, RED = 0xE8262A, GRAY = 0x3A3A3A;
const TR = [0, 0.7, 1.4, 2.1, 2.8, 3.5, 4.2, 4.9];
const BIRD_W = 0.35;                       // world width of a 3D bird
const RAY_R = 0.016;
const EXT_LEN = 8.6, HANDLE_R = 8.0;

let vAzDeg = 26.57, vElDeg = 4.79;         // default V = (0.8, 0.15, 1.6)
const V = new THREE.Vector3();
function updateV() {
  const a = THREE.MathUtils.degToRad(vAzDeg), e = THREE.MathUtils.degToRad(vElDeg);
  V.set(Math.sin(a) * Math.cos(e), Math.sin(e), Math.cos(a) * Math.cos(e)).multiplyScalar(SPEED);
}
updateV();
function birdPos(t) { return new THREE.Vector3(P0.x + V.x * t, P0.y + V.y * t, P0.z + V.z * t); }
function projOn(p, eps) {
  const z = Math.max(0.3, p.z);
  return new THREE.Vector3(FOCAL * p.x / z, FOCAL * p.y / z, FOCAL + (eps || 0));
}

/* ── groups ────────────────────────────────────────────────────────────── */
const world3D = new THREE.Group();
const planeGroup = new THREE.Group();
scene.add(world3D); scene.add(planeGroup);

/* ── bird silhouette (smooth gull: two swept wings, head bump, tail) ────── */
const BIRD_SHAPE = (() => {
  const s = new THREE.Shape();
  s.moveTo(-0.50, 0.28);
  s.quadraticCurveTo(-0.30, 0.13, -0.13, -0.02);   // left wing, underside
  s.lineTo(-0.17, -0.19);                          // tail prong
  s.quadraticCurveTo(-0.05, -0.09, 0.04, -0.07);   // body underside
  s.quadraticCurveTo(0.27, 0.09, 0.50, 0.28);      // right wing, underside
  s.quadraticCurveTo(0.30, 0.03, 0.13, 0.05);      // right wing, top edge
  s.quadraticCurveTo(0.03, 0.23, -0.07, 0.05);     // head
  s.quadraticCurveTo(-0.28, 0.05, -0.50, 0.28);    // left wing, top edge
  s.closePath();
  return s;
})();
const BIRD_GEO = new THREE.ShapeGeometry(BIRD_SHAPE, 14);
BIRD_GEO.translate(0, -0.05, 0);
const BIRD_OUT_GEO = new THREE.BufferGeometry().setFromPoints(
  BIRD_SHAPE.getPoints(14).map(p => new THREE.Vector3(p.x, p.y - 0.05, 0)));

function makeBird(order, depthTest) {
  const dt = depthTest !== false;
  const g = new THREE.Group();
  const mkMat = (c) => new THREE.MeshBasicMaterial({
    color: c, side: THREE.DoubleSide, transparent: true, opacity: 1,
    depthWrite: false, depthTest: dt
  });
  const back = new THREE.Mesh(BIRD_GEO, mkMat(0x000000));   // black halo = outline
  back.scale.set(1.13, 1.16, 1); back.position.z = -0.002; back.renderOrder = order;
  const fill = new THREE.Mesh(BIRD_GEO, mkMat(0xffffff));
  fill.position.z = 0.002; fill.renderOrder = order + 1;
  const outline = new THREE.LineLoop(BIRD_OUT_GEO, new THREE.LineBasicMaterial({
    color: 0x000000, transparent: true, opacity: 1, depthWrite: false, depthTest: dt
  }));
  outline.position.z = 0.004; outline.renderOrder = order + 2;
  g.add(back); g.add(fill); g.add(outline);
  const mats = [back.material, fill.material, outline.material];
  g.setOpacity = (o) => { for (const m of mats) m.opacity = o; };
  return g;
}

/* ── rod / arrow helpers ───────────────────────────────────────────────── */
function makeRod(color, r, order, opts = {}) {
  const geo = new THREE.CylinderGeometry(r, r, 1, 10); geo.translate(0, 0.5, 0);
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 1, depthWrite: false,
    depthTest: opts.depthTest !== false
  });
  const m = new THREE.Mesh(geo, mat);
  if (order !== undefined) m.renderOrder = order;
  m.setFromTo = function (a, b) {
    const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
    if (len < 1e-5) { this.visible = false; return; }
    this.visible = true; dir.divideScalar(len);
    this.position.copy(a);
    this.quaternion.setFromUnitVectors(UP, dir);
    this.scale.set(1, len, 1);
  };
  return m;
}
function makeArrow(color, shaftR, headR, headL, opts = {}) {
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 1,
    depthWrite: false, depthTest: opts.depthTest !== false
  });
  const g = new THREE.Group();
  const sg = new THREE.CylinderGeometry(shaftR, shaftR, 1, 12); sg.translate(0, 0.5, 0);
  const hg = new THREE.ConeGeometry(headR, headL, 16); hg.translate(0, headL / 2, 0);
  const shaft = new THREE.Mesh(sg, mat), head = new THREE.Mesh(hg, mat);
  if (opts.order !== undefined) { shaft.renderOrder = opts.order; head.renderOrder = opts.order; }
  g.add(shaft); g.add(head);
  g.userData.mat = mat; g.userData.k = 1;
  g.setThickness = function (k) {
    shaft.scale.x = shaft.scale.z = k;
    head.scale.x = head.scale.z = k;
    g.userData.k = k;
  };
  g.setFromTo = function (a, b) {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    if (len < 1e-3) { this.visible = false; return; }
    this.visible = true;
    dir.divideScalar(len);
    this.position.copy(a);
    this.quaternion.setFromUnitVectors(UP, dir);
    const hl = Math.min(headL * g.userData.k, len * 0.6);
    head.scale.y = hl / headL;
    head.position.y = len - hl;
    shaft.scale.y = Math.max(1e-4, len - hl);
  };
  return g;
}

/* ── camera centre O ───────────────────────────────────────────────────── */
const oSphere = new THREE.Mesh(new THREE.SphereGeometry(0.10, 24, 18),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));
world3D.add(oSphere);
registerInteractive(oSphere, {
  title: 'Camera centre O',
  tooltip: 'Camera centre O',
  body: 'Every projection ray passes through this single point. A world point P is imaged where the line OP pierces the image plane: p = f·(Px/Pz, Py/Pz), with f = 2.'
});

/* ── image plane: four inked edges only (invisible pick target) ────────── */
const planeFill = new THREE.Mesh(
  new THREE.PlaneGeometry(2 * PLANE_HX, 2 * PLANE_HY),
  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false })
);
planeFill.position.set(0, 0, FOCAL);
planeFill.renderOrder = 0;
planeGroup.add(planeFill);
const PC = [
  new THREE.Vector3(-PLANE_HX, -PLANE_HY, FOCAL), new THREE.Vector3(PLANE_HX, -PLANE_HY, FOCAL),
  new THREE.Vector3(PLANE_HX, PLANE_HY, FOCAL), new THREE.Vector3(-PLANE_HX, PLANE_HY, FOCAL)
];
