  back.scale.set(1.13, 1.16, 1); back.position.z = -0.002; back.renderOrder = order;
  const fill = new THREE.Mesh(BIRD_GEO, mkMat(0xffffff));
  fill.position.z = 0.002; fill.renderOrder = order + 1;
  const outline = new THREE.LineLoop(BIRD_OUT_GEO, new THREE.LineBasicMaterial({
    color: 0x000000, transparent: true, opacity: 1, depthWrite: false, depthTest: dt
  }));
  outline.position.z = 0.004; outline.renderOrder = order + 2;
  g.add(back); g.add(fill); g.add(outline);
  const mats = [back.material, fill.material, outline.material];
  g.setOpacity = (o) => { for (const m of mats) m.opacity = o; };
