}

/* ── rod / arrow helpers ───────────────────────────────────────────────── */
function makeRod(color, r, order, opts = {}) {
  const geo = new THREE.CylinderGeometry(r, r, 1, 10); geo.translate(0, 0.5, 0);
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 1, depthWrite: false,
    depthTest: opts.depthTest !== false
  });
  const m = new THREE.Mesh(geo, mat);
  if (order !== undefined) m.renderOrder = order;
  m.setFromTo = function (a, b) {
    const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
    if (len < 1e-5) { this.visible = false; return; }
    this.visible = true; dir.divideScalar(len);
    this.position.copy(a);
    this.quaternion.setFromUnitVectors(UP, dir);
    this.scale.set(1, len, 1);
  };
  return m;
}
function makeArrow(color, shaftR, headR, headL, opts = {}) {
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 1,
    depthWrite: false, depthTest: opts.depthTest !== false
  });
  const g = new THREE.Group();
  const sg = new THREE.CylinderGeometry(shaftR, shaftR, 1, 12); sg.translate(0, 0.5, 0);
  const hg = new THREE.ConeGeometry(headR, headL, 16); hg.translate(0, headL / 2, 0);
  const shaft = new THREE.Mesh(sg, mat), head = new THREE.Mesh(hg, mat);
  if (opts.order !== undefined) { shaft.renderOrder = opts.order; head.renderOrder = opts.order; }
  g.add(shaft); g.add(head);
  g.userData.mat = mat; g.userData.k = 1;
  g.setThickness = function (k) {
    shaft.scale.x = shaft.scale.z = k;
    head.scale.x = head.scale.z = k;
    g.userData.k = k;
  };
  g.setFromTo = function (a, b) {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    if (len < 1e-3) { this.visible = false; return; }
    this.visible = true;
    dir.divideScalar(len);
    this.position.copy(a);
    this.quaternion.setFromUnitVectors(UP, dir);
    const hl = Math.min(headL * g.userData.k, len * 0.6);
    head.scale.y = hl / headL;
    head.position.y = len - hl;
    shaft.scale.y = Math.max(1e-4, len - hl);
  };
  return g;
}

