let tCur = 1.2;
const projPts = new Array(TR.length);
let labO = null, labV3 = null, labVe = null, labVP = null;
const _qInv = new THREE.Quaternion();
const _vCam = new THREE.Vector3();

function update() {
  updateV();
  const vhat = V.clone().normalize();

  _qInv.copy(camera.quaternion).invert();
  _vCam.copy(vhat).applyQuaternion(_qInv);
  const screenAng = Math.atan2(_vCam.y, _vCam.x);

  const vp = new THREE.Vector3(FOCAL * V.x / V.z, FOCAL * V.y / V.z, FOCAL + 0.02);
  vpDot.position.copy(vp);

  for (let i = 0; i < TR.length; i++) {
