    const pb = projBirds[i];
    pb.position.copy(q);
    pb.rotation.set(0, 0, Math.atan2(vp.y - q.y, vp.x - q.x));
    pb.scale.setScalar(Math.max(0.03, BIRD_W * FOCAL / Math.max(0.3, p.z)));
    pb.setOpacity(TR[i] < tCur - 1e-6 ? 0.6 : 1);
